   76	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableUnit
   77	    {
   78	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   79	        if ($profile === null) {
   80	            return null;
   81	        }
   82	
   83	        if (! User::query()->whereKey($playerId)->exists()) {
   84	            return null;
   85	        }
   86	
   87	        $player ??= $this->playerServiceFactory->make($playerId, true);
   88	        $planets = $player->planets->all();
   89	        if ($planets === []) {
   90	            return null;
   91	        }
   92	
   93	        $underAttack = $this->underAttack($player);
   94	
   95	        // Whether the pass below has a planet to serve. A sibling that stands no wall while one
   96	        // already does owns the account's wall effort: the pass serves it, and when it cannot be
   97	        // served the building planner's own wall pass stands the yard it waits on. Adding wall
   98	        // where one already stands instead is the shape the invariant reads -- a planet at zero
   99	        // defence beside a sibling holding a wall -- so nothing below collects more wall while a
  100	        // sibling is still bare (measured live 3 Oct 2026: a planet at zero beside one holding
  101	        // 1,225 units).
  102	        $nakedBesideWalled = $this->nakedBesideWalled($planets);
  103	
  104	        // Standing defence is collected across the account and chosen once at the end. Returning on
  105	        // the first planet that wanted anything let the planet with the most to lose take every order:
  106	        // need grows with production, so the homeworld's need was never satisfied and its colonies were
  107	        // never reached -- 125 of 158 grand-test planets sat at zero defence while one held 40,643.
  108	        $standing = [];
  109	
  110	        // A planet that stands no defence beside a sibling that already holds one takes the file's
  111	        // floor before every other role, and across the whole account. It is also the only planet the
  112	        // account may buy wall for: the survivor below is the bare sibling, and the walled planets
  113	        // are left alone until it is served, so a login's one wall order cannot be stacked where a
  114	        // wall already stands. The roles below are per planet
  115	        // and each can keep re-firing on a single planet -- power for a planet that stays short, a
  116	        // cargo fleet that never catches the next report, a colony ship for the next planet -- so the
  117	        // naked planet was answered only when every one of those happened to fall quiet, and the
  118	        // account stayed walled in one place (measured live 2 Oct 2026: 1 naked planet beside a
  119	        // sibling holding 1,475). While no wall stands anywhere the account is still in its opening,
  120	        // where cargo comes first; the standing pass below still reaches the floor for that case.
  121	        if ($this->anyPlanetHoldsDefence($planets)) {
  122	            foreach ($planets as $planet) {
  123	                // The balance is refreshed before the wall is priced: the host refuses an unaffordable batch.
  124	                $planet->updateResources(false);
  125	                // Defence already paid for in the yard counts as standing: a planet whose first wall is
  126	                // ordered is no longer bare, so the next bare sibling takes the order instead of the same
  127	                // planet taking every one while its sibling stays at zero built units. The account can
  128	                // only place one wall order per session, so the pass walks the planets in order and
  129	                // leaves the already-served ones to the next login.
  130	                if ($this->defenseNeed->standingUnits($planet) > 0) {
  131	                    continue;
  132	                }
  133	
  134	                $standingDefence = $this->standingDefence($player, $planet);
  135	                if ($standingDefence === null) {
  136	                    continue;
  137	                }
  138	
  139	                return $standingDefence;
  140	            }
  141	        }
  142	
  143	        // Power outranks the habits below but not an incoming attack. A planet that is throttling
  144	        // loses production every hour it stays short, wherever it sits on the account, so it is
  145	        // answered before a habit on another planet gets its turn -- the same reason the building
  146	        // planner runs its storage pass before its routine. The building planner has already
  147	        // refreshed every planet's balance earlier in this perception, so the shortfall read here
  148	        // is the session's own.
  149	        if (! $underAttack) {
  150	            foreach ($planets as $planet) {
  151	                $power = $this->powerFromYard($planet);
  152	                if ($power !== null) {
  153	                    return $power;
  154	                }
  155	            }
  156	        }
  157	
  158	        foreach ($planets as $planet) {
  159	            $planet->updateResources(false);
  160	
  161	            // Whether this planet wants a wall, and how big. Asked before the wall is composed so
  162	            // the same answer sizes both the reactive and the standing defence below.
  163	            $need = $this->defenseNeed->evaluate($player, $planet);
  164	
  165	            // Cargo first, and only while the account owns no ship at all: a fleet begins with
  166	            // one hull that can carry. A planet that owns nothing but cannot queue one yet still
  167	            // falls through -- defence is reactive and standing, and waiting for a hull is what
  168	            // left a fleetless account with no wall of its own.
  169	            if ($this->ownsNoShip($planet)) {
  170	                $cargo = $this->bestCargo($player, $planet);
  171	                if ($cargo !== null) {
  172	                    return $this->unit($planet, $cargo, 'role:cargo:'.$cargo->machine_name);
  173	                }
  174	            }
  175	
  176	            // Defence is reactive and time-sensitive: an inbound hostile makes it worth buying
  177	            // before anything else on this planet, and the host's own "under attack" is the
  178	            // trigger, so the module keeps no mission-type list.
  179	            if ($underAttack) {
  180	                $defense = $this->defenseComposition->plan($player, $planet, $need);
  181	                if ($defense !== null) {
  182	                    return $this->unit($planet, $defense->unit, 'role:defense:'.$defense->unit->machine_name, $defense->amount);
  183	                }
  184	            }
  185	
  186	            // Expansion: a colony ship once a fleet exists, the account has room, and none is
  187	            // already owned. One colony ship is the second planet every later fleet move needs.
  188	            if (! $this->ownsColonyShip($planet) && $player->planets->planetCount() < $player->getMaxPlanetAmount()) {
  189	                $colonyShip = ObjectService::getUnitObjectByMachineName(ColonisationMission::getRequiredShipMachineNames()[0]);
  190	                if ($this->queueable($planet, $colonyShip)) {
  191	                    return $this->unit($planet, $colonyShip, 'role:colony');
  192	                }
  193	            }
  194	
  195	            // Scouting: a probe once a fleet exists, so the account can start seeing neighbours.
