  283	    /**
  284	     * What a player does with a full yard and nothing urgent: spends half of what the richest planet
  285	     * can afford on the strongest military hull the host lets it build, so the war fleet grows as
  286	     * research unlocks bigger hulls and a mod-added hull counts with no edit. Strongest is the
  287	     * catalogue's own price order; the economy's saving can still veto the order.
  288	     *
  289	     * @param array<int, PlanetService> $planets
  290	     */
  291	    private function capitalFleet(PlayerService $player, array $planets, AiProfile $profile): ?QueueableUnit
  292	    {
  293	        usort($planets, static fn (PlanetService $a, PlanetService $b): int => $b->metal()->get() <=> $a->metal()->get());
  294	
  295	        foreach ($planets as $planet) {
  296	            $hulls = array_filter(
  297	                ObjectService::getMilitaryShipObjects(),
  298	                fn (UnitObject $hull): bool => $this->canAttack($player, $hull) && $this->queueable($planet, $hull),
  299	            );
  300	            if ($hulls === []) {
  301	                continue;
  302	            }
  303	
  304	            usort($hulls, fn (UnitObject $a, UnitObject $b): int => $this->hullPrice($planet, $b) <=> $this->hullPrice($planet, $a));
  305	            $hull = $hulls[0];
  306	            $amount = max(self::FIRST_CARGO_AMOUNT, intdiv($this->affordable($planet, $hull), 2));
  307	            if ($this->starvesSaving($planet, $profile, $hull, $amount)) {
  308	                continue;
  309	            }
  310	
  311	            return $this->unit($planet, $hull, 'role:capital:'.$hull->machine_name, $amount);
  312	        }
  313	
  314	        return null;
  315	    }
