  317	    /** A hull that shoots: probes and satellites are military in the catalogue's grouping but fight nothing. */
  318	    private function canAttack(PlayerService $player, UnitObject $hull): bool
  319	    {
  320	        return $hull->properties->attack->calculate($player)->totalValue > 1;
  321	    }
  322	
  323	    private function hullPrice(PlanetService $planet, UnitObject $hull): float
  324	    {
  325	        $price = ObjectService::getObjectPrice($hull->machine_name, $planet);
  326	
  327	        return $price->metal->get() + $price->crystal->get() + $price->deuterium->get();
  328	    }
