  331	     * The colony ship a colonisation still lacks: a player with a free slot and no ship at the origin
  332	     * orders the ship first. Null when the ship is there already or the yard cannot take it yet.
  333	     */
  334	    public function colonyShipFor(int $playerId, int $planetId): QueueableUnit|null
  335	    {
  336	        $planet = collect($this->playerServiceFactory->make($playerId, true)->planets->all())
  337	            ->first(fn (PlanetService $candidate): bool => $candidate->getPlanetId() === $planetId);
  338	        $ship = ObjectService::getUnitObjectByMachineName(ColonisationMission::getRequiredShipMachineNames()[0]);
  339	
  340	        if ($planet === null || $this->ownsColonyShip($planet) || ! $this->queueable($planet, $ship)) {
  341	            return null;
  342	        }
  343	
  344	        return $this->unit($planet, $ship, 'role:colony');
  345	    }
