  347	    private function unit(PlanetService $planet, UnitObject $ship, string $reason, int $amount = self::FIRST_CARGO_AMOUNT, bool $aheadOfEconomy = false): QueueableUnit
  348	    {
  349	        return app()->makeWith(QueueableUnit::class, [
  350	            'planetId' => $planet->getPlanetId(),
  351	            'unitId' => $ship->id,
  352	            'amount' => $amount,
  353	            'reason' => $reason,
  354	            'aheadOfEconomy' => $aheadOfEconomy,
  355	        ]);
  356	    }
