  359	     * The cargo batch a raidable fresh report asks for, once the opening fleet
  360	     * exists: expected loot (the host's class loot fraction of the largest
  361	     * visible pile) plus a 20% buffer, minus what the fleet already carries.
  362	     */
  363	    private function cargoForPayload(PlayerService $player, PlanetService $planet, int $playerId): ?QueueableUnit
  364	    {
  365	        $cargo = $this->bestCargo($player, $planet);
  366	        if ($cargo === null) {
  367	            return null;
  368	        }
  369	
  370	        $loot = $this->expectedRaidLoot($player, $playerId);
  371	        if ($loot <= 0) {
  372	            return null;
  373	        }
  374	
  375	        // The cargo role is chosen for a positive capacity, so the capacity is
  376	        // non-zero by the time it is sized.
  377	        $capacity = $cargo->properties->capacity->calculate($player)->totalValue;
  378	        $needed = (int) ceil($loot * 1.2 / $capacity);
  379	        $owned = (int) floor($planet->getShipUnits()->getTotalCargoCapacity($player) / $capacity);
  380	        $missing = min($needed - $owned, ObjectService::getObjectMaxBuildAmount($cargo->machine_name, $planet, true));
  381	
  382	        if ($missing <= 0) {
  383	            return null;
  384	        }
  385	
  386	        return $this->unit($planet, $cargo, 'role:cargo:payload', $missing);
  387	    }
